window.MONSTER_CHUNK_73 = [{"name":"Korir-kokembe","cr":10,"xp":9600,"alignment":"N","size":"Huge","type":"dragon","init":6,"senses":[{"type":"darkvision","modifier":"60 ft."},{"type":"low-light vision"},{"type":"scent"}],"auras":["frightful presence (30 ft., DC 18)"],"ac":24,"ac_touch":10,"ac_flat_footed":22,"ac_mods":"+2 Dex, +14 natural, -2 size","hp":136,"hd":"13d12+52","hdvalue":13,"fort":12,"ref":12,"will":10,"immunities":["disease","dragon traits","magic paralysis and sleep"],"speed":[{"type":"land","speed":40},{"type":"climb","speed":40},{"type":"fly","speed":80,"maneuverability":"good"},{"type":"swim","speed":40}],"melee":"bite +18 (2d6+10 plus disease and grab), 2 claws +18 (2d6+7/19-20 plus grab), tail slap +13 (2d6+3 plus grab)","space":"15 ft.","reach":"15 ft. (20 ft. with bite)","special_attacks":[{"type":"constrict","details":"2d6+7"},{"type":"grab","details":"Gargantuan"},{"type":"rake","details":"2 claws +18, 2d6+7/19-20"}],"spell_like_abilities_caster_level":13,"spell_like_abilities_concentration":17,"spell_like_abilities":[{"frequency":"constant","spells":[{"spell":"freedom of movement"}]},{"frequency":"at-will","spells":[{"spell":"repel vermin"},{"spell":"vomit swarm","details":"must wait 1d4 rounds before using this ability again"}]},{"frequency":"1/day","spells":[{"spell":"creeping doom"},{"spell":"insect plague"}]},{"frequency":"3/day","spells":[{"spell":"entangle"}]}],"strength":25,"dexterity":15,"constitution":18,"intelligence":10,"wisdom":14,"charisma":15,"baseatk":13,"cmb":22,"cmb_special":"+4 vs. grapple","cmd":34,"cmd_special":"+12 vs. trip","feats":[{"feat":"Critical Focus"},{"feat":"Improved Critical (claw)"},{"feat":"Improved Initiative"},{"feat":"Lightning Reflexes"},{"feat":"Power Attack"},{"feat":"Sickening Critical"},{"feat":"Wingover"}],"skills":[{"skill":"Climb","value":21},{"skill":"Fly","value":15},{"skill":"Intimidate","value":15},{"skill":"Knowledge (nature)","value":13},{"skill":"Perception","value":18},{"skill":"Spellcraft","value":10},{"skill":"Stealth","value":10,"special":"+18 in jungles"},{"skill":"Survival","value":10},{"skill":"Swim","value":25}],"languages":["Draconic"],"sq":[{"type":"compression"}],"environments":["warm jungles (Mwangi Expanse)"],"organizations":["solitary","nest (2-5)"],"treasure":"standard","description_visual":"This green-tined dragon has multiple sets of legs down its long, sinuous body. An oversized gullet bulges in its throat.","source":"Inner Sea Bestiary","special_abilities":[{"type":"Disease","kind":"Ex","details":"Bite-injury; save Fort DC 20; onset 1 round; frequency 1 day; effect 1d3 Dex damage and 1d3 Str damage; cure 2 consecutive saves."}],"description":"Korir-kokembe live in the deep, watery jungles of central Garund, plaguing the major rivers and lake systems. While young korir-kokembe may swim near populated waterways to claim their prey, their elder kin prefer more remote backwaters, sloughs, and heavily wooded swamps where they can hunt undisturbed. These degenerate dragons live in a violent symbiosis with the tiny vermin that infest the jungle, hosting colonies of such creatures within their own bodies. Such tiny vermin constantly swarm in and out of the korir-kokembe's gullet, bringing contagion to creatures bitten and allowing the wyrm to expel swarms of pests, or to summon yet more vermin to its aid. While korir-kokembe are capable of flight, they generally prefer to crawl or climb on their eight legs, hunching their bodies like inchworms or twining their coils around their prey while savaging creatures with a barrage of slashing claws.","ecology":"","habitat_society":""},{"name":"Kronosaurus","cr":10,"xp":9600,"alignment":"N","size":"Gargantuan","type":"animal","init":1,"senses":[{"type":"low-light vision"},{"type":"scent"}],"ac":23,"ac_touch":7,"ac_flat_footed":22,"ac_mods":"+1 Dex, +16 natural, -4 size","hp":138,"hd":"12d8+84","hdvalue":12,"fort":15,"ref":9,"will":7,"speed":[{"type":"swim","speed":60}],"melee":"bite +19 (3d8+19/19-20 plus grab)","space":"20 ft.","reach":"20 ft.","special_attacks":[{"type":"swallow whole","details":"3d6+12 damage, AC 18, 13 hp"}],"strength":36,"dexterity":13,"constitution":24,"intelligence":2,"wisdom":13,"charisma":9,"baseatk":9,"cmb":26,"cmb_special":"+4 vs. grapple","cmd":37,"cmd_special":"can't be tripped","feats":[{"feat":"Endurance"},{"feat":"Improved Critical (bite)"},{"feat":"Iron Will"},{"feat":"Power Attack"},{"feat":"Skill Focus (Perception)"},{"feat":"Weapon Focus (bite)"}],"skills":[{"skill":"Perception","value":20},{"skill":"Swim","value":26}],"environments":["warm oceans"],"organizations":["solitary","pair","school (3-8)"],"treasure":"none","description_visual":"This enormous, finned reptile has a long mouth full of sharp teeth and moves through the water with incredible speed.","source":"AP 60","description":"The mighty kronosaurus is a relentless hunter that, once it picks up a potential meal's scent, rarely stops seeking its prey until its appetite is sated. A kronosaurus's diet consists of everything from large fish and sharks to small whales, giant squids, and sea turtles. Remains of other giant saurians have reportedly been found in the stomachs of those rare kronosauruses that are killed by hunters or wash up dead on shore. Unlike other reptiles, a kronosaurus doesn't lay eggs, but instead births its young live. The young kronosauruses stay with their mother for less than a year before parting ways and hunting on their own. A fully grown kronosaurus can reach lengths of up to 50 ft. and weigh as much as 40,000 pounds.","ecology":"","habitat_society":""},{"name":"Magnetite Golem","cr":10,"xp":9600,"alignment":"N","size":"Large","type":"construct","init":-1,"senses":[{"type":"darkvision","modifier":"60 ft."},{"type":"low-light vision"}],"auras":["magnetic field (30 ft.)"],"ac":24,"ac_touch":8,"ac_flat_footed":24,"ac_mods":"-1 Dex, +16 natural, -1 size","hp":101,"hd":"13d10+30","hdvalue":13,"fort":4,"ref":3,"will":5,"dr":"10/adamantine","immunities":["construct traits","magic"],"speed":[{"type":"land","speed":20}],"melee":"2 slams +20 (2d10+8 plus inescapable grip and  magnetic disarm)","space":"10 ft.","reach":"10 ft.","special_attacks":[{"type":"inescapable grip"},{"type":"magnetic disarm"}],"strength":27,"dexterity":9,"wisdom":12,"charisma":1,"baseatk":13,"cmb":22,"cmb_special":"+4 vs. grapple","cmd":31,"environments":["any"],"organizations":["solitary","gang (2-4)"],"treasure":"incidental (metal objects stuck to the golem)","description_visual":"This vaguely humanoid mass of polished black metal lumbers forward, with all manner of metallic objects clinging to its body.","group":"Golem","source":"AP 95","special_abilities":[{"type":"Immunity to Magic","kind":"Ex","details":"A magnetite golem is immune to any spell or spell-like ability that allows spell resistance. In addition, certain spells and effects function differently against the creature, as noted below. • Any spell that deals fire damage instead disables a magnetite golem's inescapable grip, magnetic disarm, and magnetic field for 1d4 rounds, with no saving throw. • A magical attack that deals electricity damage heals 1 point of damage for every 3 points of damage the attack would otherwise deal. If the amount of healing would cause the golem to exceed its full normal hit points, it gains any excess as temporary hit points. A magnetite golem receives no saving throw against electricity effects."},{"type":"Inescapable Grip","kind":"Ex","details":"Whenever a magnetite golem hits a metallic creature or a creature wearing metal armor with its slam attack, it attempts to grapple the creature as a free action that doesn't provoke an attack of opportunity. If a magnetite golem successfully grapples such a creature, it partially adheres to the golem's body, and the golem needs only one arm to maintain the grapple. In these instances, a magnetite golem may still make a single slam attack on its turn with its remaining arm."},{"type":"Magnetic Disarm","kind":"Su","details":"Whenever a magnetite golem hits a creature wielding a metal weapon with its slam attack, it attempts to disarm the weapon as a free action that doesn't provoke attacks of opportunity. If the golem successfully disarms a metal weapon, the weapon sticks to the golem's magnetic body rather than dropping to the ground. The golem is considered to have possession of the weapon, and the weapon must be retrieved using a disarm combat maneuver."},{"type":"Magnetic Field","kind":"Su","details":"A magnetite golem is surrounded by a magnetic field, which pulls all metallic creatures and objects toward it. At the start of a magnetite golem's turn, as a free action that doesn't provoke attacks of opportunity, the golem attempts a combat maneuver check against every creature within 30 ft. that is connected to a piece of metal. Affected creatures include (but are not limited to) metallic creatures, creatures wearing metal armor, and creatures wielding metal weapons. If the golem succeeds at its combat maneuver against a creature, the affected creature is pulled 10 ft. closer to the golem, and can't move away from the golem during its next round. The magnetic field is stronger than gravity, and can pull creatures off the ground. This movement doesn't provoke attacks of opportunity. Unattended Large or smaller metal objects automatically travel toward magnetite golem at a rate of 10 ft. per round. This magnetism is supernatural in nature and affects all metal objects."}],"description":"Though softer than iron golems-upon whom their design is based-and problematic in most industrial settings, magnetite golems still prove to be useful, specialized constructs for both security and salvage. A magnetite golem's humanoid body is made of magnetite, a naturally magnetic mineral. A magnetite golem mindlessly obeys its creator's instructions, and, like most golems, shrugs off the most devastating magical assaults. To complicate matters, a magnetite golem emits a magnetic field, which forcefully pulls metallic objects closer-including creatures holding metal weapons or clad in metal armor. Once within range, metal-bearing opponents find it difficult to pull themselves away. Magnetite golems specialize in grappling and disarming creatures that rely on metal equipment.\n\nMagnetite golems are usually about 9 ft. tall, and weigh approximately 1,500 pounds.\n\nEcology\n\nMagnetite golems prove tricky to build for even experienced golem crafters. Because of the sheer amount of magnetite required for their construction, these golems must be constructed in specially designed workshops with brass, stone, or wooden tools.\n\nWhile magnetite golems are invaluable in specific circumstances, they are equally inconvenient in other instances. Due to the golems' magnetic fields, small metal bits constantly fly toward them and cling to their bodies, perpetually covering them in metal detritus-chains\n\nfittings, scrap metal, and the occasional tool or weapon. A golem's owner must regularly pry off such debris, lest the clinging metal clog the construct's joints. Additionally, the golem's magnetic field prohibits using any kind of mundane metal objects (like basic tools, locks, or nails) nearby. Due to this, wealthy individuals in the market for golems usually purchase iron, stone, or wood golems. However, in the rare cases in which a magnetite golem is the perfect tool for the job, it proves a devastatingly effective weapon.\n\nHabitat & Society\n\nMagnetite golems have existed on Golarion for many millennia. Explorers delving into Thassilonian ruins occasionally come across these hulking guardians. In Edasseril, the Thassilonian nation tied to the sin of envy, some powerful wizards commanded magnetite golems, and delighted in the constructs' ability to seize their foes' prized possessions.\n\nBecause of the unique difficulties associated with the crafting of magnetite golems, the production of new specimens is a rare event. Only a few workshops-such as Magnimar's famous Golemworks or the forges of Quantium-have the resources necessary to create these golems.\n\nMost magnetite golems toil as guardians. A few individuals use magnetite golems for private security, including particularly wealthy alchemists and mages who wish to protect nonmetallic caches of alchemical reagents, artwork, spell components, or tomes. A few jealous warlords even protect their legendary armor or weapons by attaching them to the backs of magnetite golem guardians. For eccentrics who work exclusively with glass, paper, or wood, magnetite golems are ideal companions. Magnetite golems are sometimes tasked to guard lightly trafficked areas that hold objects of cultural, historical, or material value, such as spacious tombs or far-flung libraries.\n\nA few paranoid aristocrats and wealthy thieves' guilds station magnetite golems at their visitor's entrances, as the inexorable pull of the golems' auras reveal even the most thoroughly hidden weapons. Individuals with substantial wealth may also station magnetite golems in secret passageways leading to their hidden vaults. Even if a magnetite golem fails to notice an intruder, its magnetic aura\n\nstill pulls the intruder and her metallic gear closer. The thundering crash of metal objects striking the golem conveniently alerts other nearby guardians.\n\nConstruction\n\nA magnetite golem's body is sculpted from 1,500 pounds of pure magnetite, smelted with rare oils worth 5,000 gp.\n\nMAGNETITE GOLEM\n\nCL 13th; Price 90,000 gp\n\nConstruction\n\nRequirements Craft Construct, geas/quest, limited wish, reverse gravity, telekinesis, creator must be caster level 13th; Skill Craft (armor) or Craft (weapons) DC 18; Cost 47,500 gp","ecology":"Magnetite golems prove tricky to build for even experienced golem crafters. Because of the sheer amount of magnetite required for their construction, these golems must be constructed in specially designed workshops with brass, stone, or wooden tools.\n\nWhile magnetite golems are invaluable in specific circumstances, they are equally inconvenient in other instances. Due to the golems' magnetic fields, small metal bits constantly fly toward them and cling to their bodies, perpetually covering them in metal detritus-chains\n\nfittings, scrap metal, and the occasional tool or weapon. A golem's owner must regularly pry off such debris, lest the clinging metal clog the construct's joints. Additionally, the golem's magnetic field prohibits using any kind of mundane metal objects (like basic tools, locks, or nails) nearby. Due to this, wealthy individuals in the market for golems usually purchase iron, stone, or wood golems. However, in the rare cases in which a magnetite golem is the perfect tool for the job, it proves a devastatingly effective weapon.","habitat_society":"Magnetite golems have existed on Golarion for many millennia. Explorers delving into Thassilonian ruins occasionally come across these hulking guardians. In Edasseril, the Thassilonian nation tied to the sin of envy, some powerful wizards commanded magnetite golems, and delighted in the constructs' ability to seize their foes' prized possessions.\n\nBecause of the unique difficulties associated with the crafting of magnetite golems, the production of new specimens is a rare event. Only a few workshops-such as Magnimar's famous Golemworks or the forges of Quantium-have the resources necessary to create these golems.\n\nMost magnetite golems toil as guardians. A few individuals use magnetite golems for private security, including particularly wealthy alchemists and mages who wish to protect nonmetallic caches of alchemical reagents, artwork, spell components, or tomes. A few jealous warlords even protect their legendary armor or weapons by attaching them to the backs of magnetite golem guardians. For eccentrics who work exclusively with glass, paper, or wood, magnetite golems are ideal companions. Magnetite golems are sometimes tasked to guard lightly trafficked areas that hold objects of cultural, historical, or material value, such as spacious tombs or far-flung libraries.\n\nA few paranoid aristocrats and wealthy thieves' guilds station magnetite golems at their visitor's entrances, as the inexorable pull of the golems' auras reveal even the most thoroughly hidden weapons. Individuals with substantial wealth may also station magnetite golems in secret passageways leading to their hidden vaults. Even if a magnetite golem fails to notice an intruder, its magnetic aura\n\nstill pulls the intruder and her metallic gear closer. The thundering crash of metal objects striking the golem conveniently alerts other nearby guardians.\n\nConstruction\n\nA magnetite golem's body is sculpted from 1,500 pounds of pure magnetite, smelted with rare oils worth 5,000 gp.\n\nMAGNETITE GOLEM\n\nCL 13th; Price 90,000 gp\n\nConstruction\n\nRequirements Craft Construct, geas/quest, limited wish, reverse gravity, telekinesis, creator must be caster level 13th; Skill Craft (armor) or Craft (weapons) DC 18; Cost 47,500 gp"},{"name":"Minor Grim Reaper","cr":10,"xp":9600,"alignment":"NE","size":"Medium","type":"undead","subtypes":["evil","extraplanar"],"init":8,"senses":[{"type":"darkvision","modifier":"60 ft."},{"type":"low-light vision"}],"ac":22,"ac_touch":14,"ac_flat_footed":18,"ac_mods":"+4 Dex, +8 natural","hp":127,"hd":"15d8+60","hdvalue":15,"fort":8,"ref":11,"will":9,"dr":"5/cold iron or good","immunities":["cold","undead traits"],"sr":21,"speed":[{"type":"land","speed":30}],"melee":"scythe +14 (2d4+3/x4 plus death touch)","space":"5 ft.","reach":"5 ft.","special_attacks":[{"type":"fear cone","details":"30 ft., DC 20"}],"strength":14,"dexterity":19,"intelligence":8,"wisdom":11,"charisma":17,"baseatk":11,"cmb":15,"cmd":27,"feats":[{"feat":"Agile Maneuvers"},{"feat":"Cleave"},{"feat":"Combat Reflexes"},{"feat":"Improved Initiative"},{"feat":"Lightning Reflexes"},{"feat":"Power Attack"},{"feat":"Toughness"},{"feat":"Weapon Focus (scythe)"}],"skills":[{"skill":"Climb","value":10},{"skill":"Intimidate","value":16},{"skill":"Perception","value":18},{"skill":"Stealth","value":22}],"sq":[{"type":"sole target"}],"environments":["any"],"organizations":["solitary","omen (2-4)"],"treasure":"none","description_visual":"This tall, cloaked figure stares out from the black hood that covers its head. It wields an enormous scythe in its skeletal, bone-white hands, looking as though it is freezing the very air around it.","group":"Grim Reaper","source":"AP 48","special_abilities":[{"type":"Death Touch","kind":"Su","details":"Creatures hit by either a lesser reaper's touch attack or by a weapon wielded by a lesser reaper must succeed at a DC 20 Fortitude save or gain 1d4 negative levels. The save DC is Charisma-based. A humanoid slain by a reaper's death touch is consumed in unholy fire and has its remains destroyed as the destruction spell. This is a death effect."},{"type":"Sole Target","kind":"Su","details":"Each minor reaper is assigned a specific target by the reaper that summoned it. If a creature attacks a minor reaper targeting another creature, that minor reaper may immediately summon another minor reaper as a free action to battle the interceding creature unless the interloper is already in battle with a minor reaper of its own, in which case the ability is wasted. If a minor reaper doesn't or cannot use this ability immediately after being attacked, it must wait until it is attacked once again in order to do so."}],"description":"Known by many names throughout nearly all cultures, grim reapers are the personifications of death and all the pain and fear associated with that state. They are universally feared by the living as harbingers of destruction and masters of all that has already passed from life. These hooded beings travel through the planes with the sole intent of bringing about the end of life, slaying with a deliberateness inscrutable to all but themselves.\n\nWhile grim reapers are the most feared of their kind, they are not alone. The towering, ghostlike grim reapers are served by minor reapers, corporeal servitors that enact their master's dreadful will and meet out death's unrelenting touch. A grim reaper is 15 ft. tall and, as an incorporeal creature, has no physical weight except for its equipment. Minor reapers stand 7 ft. tall and weigh approximately 70 pounds.\n\nEcology Grim reapers have no creator and are not born by any definition of the word-they simply exist, much as the multiverse itself does. Some philosophers argue that grim reapers were created along with the Negative Energy Plane, manifesting from this plane when mortalkind first realized death's terminal permanency. Others claim that multiple minor reapers meeting on the Negative Energy Plane or another area infused with overwhelming negative energy might join together to form a new grim reaper.\n\nWhile similar in shape to the psychopomps who serve Pharasma and ferry souls to their fates upon the planes, reapers care little for mortal souls, reveling in the moment of death and dissolution of the impermanent, regardless of the elaborate bureaucracy that oversees the doomed.\n\nHabitat & Society While grim reapers stalk the planes, spreading death and despair for their own sakes, they are not alone in their endeavors. Among their many powers, grim reapers can summon lesser versions of themselves to seek out and kill specific individuals.\n\nThese minor reapers are encountered far more often than their masters, either in the service of their masters or summoned by evil magic-users to do their foul bidding. While stripped of their more powerful brethren's necromantic powers, these minor reapers are nonetheless brutal hunters and stop at nothing to achieve their objective. Minor reapers usually wait until their target is alone before appearing for battle, though if a pack of these undead assassins are sent after a group of victims, they will engage multiple targets if necessary.\n\nIf summoned by a grim reaper, minor reapers act as its additional eyes and ears, and if they are destroyed, their master is immediately aware of their obliteration. Other times, a grim reaper may summon minor reapers to aid in its escape from a battle it expects to lose, and flees to another plane of existence where it may recover and better prepare for the annihilation of its targets.\n\nGrim reapers possess the ability to speak to any intelligent being, and the few who have survived encounters with a reaper or its minions claim that the bringer of death spoke to them in a deep, unearthly voice like nothing in the material realm.\n\nMinor reapers can be created by casters of 20th level or higher using the spell create greater undead.","ecology":"Grim reapers have no creator and are not born by any definition of the word-they simply exist, much as the multiverse itself does. Some philosophers argue that grim reapers were created along with the Negative Energy Plane, manifesting from this plane when mortalkind first realized death's terminal permanency. Others claim that multiple minor reapers meeting on the Negative Energy Plane or another area infused with overwhelming negative energy might join together to form a new grim reaper.\n\nWhile similar in shape to the psychopomps who serve Pharasma and ferry souls to their fates upon the planes, reapers care little for mortal souls, reveling in the moment of death and dissolution of the impermanent, regardless of the elaborate bureaucracy that oversees the doomed.","habitat_society":"While grim reapers stalk the planes, spreading death and despair for their own sakes, they are not alone in their endeavors. Among their many powers, grim reapers can summon lesser versions of themselves to seek out and kill specific individuals.\n\nThese minor reapers are encountered far more often than their masters, either in the service of their masters or summoned by evil magic-users to do their foul bidding. While stripped of their more powerful brethren's necromantic powers, these minor reapers are nonetheless brutal hunters and stop at nothing to achieve their objective. Minor reapers usually wait until their target is alone before appearing for battle, though if a pack of these undead assassins are sent after a group of victims, they will engage multiple targets if necessary.\n\nIf summoned by a grim reaper, minor reapers act as its additional eyes and ears, and if they are destroyed, their master is immediately aware of their obliteration. Other times, a grim reaper may summon minor reapers to aid in its escape from a battle it expects to lose, and flees to another plane of existence where it may recover and better prepare for the annihilation of its targets.\n\nGrim reapers possess the ability to speak to any intelligent being, and the few who have survived encounters with a reaper or its minions claim that the bringer of death spoke to them in a deep, unearthly voice like nothing in the material realm.\n\nMinor reapers can be created by casters of 20th level or higher using the spell create greater undead."},{"name":"Mobogo","cr":10,"xp":9600,"alignment":"CE","size":"Huge","type":"magical beast","subtypes":["aquatic"],"init":2,"senses":[{"type":"darkvision","modifier":"60 ft."},{"type":"low-light vision"}],"ac":24,"ac_touch":10,"ac_flat_footed":22,"ac_mods":"+2 Dex, +14 natural, -2 size","hp":136,"hd":"13d10+65","hdvalue":13,"hp_mods":["regeneration 5 (acid, cold, or fire)"],"fort":13,"ref":10,"will":8,"speed":[{"type":"land","speed":30},{"type":"fly","speed":30,"maneuverability":"poor"},{"type":"swim","speed":40}],"melee":"bite +20 (2d6+9), 2 slams +20 (1d8+9) or tongue +20 (1d6+9 plus grab and pull)","space":"15 ft.","reach":"15 ft. (45 ft. with tongue)","special_attacks":[{"type":"crush","details":"DC 21, 2d8+13"},{"type":"pull","details":"tongue, 5 ft."},{"type":"swallow whole","details":"2d6+13 bludgeoning damage, AC 17, 13 hp"},{"type":"vile croak"}],"spell_like_abilities_caster_level":8,"spell_like_abilities_concentration":13,"spell_like_abilities":[{"frequency":"constant","spells":[{"spell":"pass without trace"},{"spell":"speak with animals"}]},{"frequency":"at-will","spells":[{"spell":"charm animal"},{"spell":"create water"},{"spell":"sound burst"}]},{"frequency":"3/day","spells":[{"spell":"control water"},{"spell":"fog cloud"},{"spell":"gust of wind"},{"spell":"plant growth"},{"spell":"quench"},{"spell":"soften earth and stone"}]}],"strength":28,"dexterity":15,"constitution":21,"intelligence":6,"wisdom":15,"charisma":16,"baseatk":13,"cmb":24,"cmb_special":"+4 vs. grapple, +2 vs. overrun","cmd":36,"cmd_special":"+2 vs. overrun, +4 vs. trip","feats":[{"feat":"Awesome Blow"},{"feat":"Cleave"},{"feat":"Combat Reflexes"},{"feat":"Improved Bull Rush"},{"feat":"Improved Overrun"},{"feat":"Iron Will"},{"feat":"Power Attack"}],"skills":[{"skill":"Acrobatics","value":9,"special":"+17 when jumping"},{"skill":"Fly","value":-6},{"skill":"Perception","value":19},{"skill":"Stealth","value":0,"special":"+8 in swamps"},{"skill":"Swim","value":17}],"languages":["Boggard","speak with animals"],"sq":[{"type":"amphibious"},{"type":"swamp stride"}],"environments":["temperate swamps"],"organizations":["solitary","gang (2-4)"],"treasure":"standard","description_visual":"This grotesque creature looks like a gigantic toad with leathery wings, fangs, horns, and three bulbous eyes.","source":"PFRPG Bestiary 3","special_abilities":[{"type":"Swamp Stride","kind":"Ex","details":"A mobogo can move through any sort of natural difficult terrain at its normal speed while within a swamp. Magically altered terrain affects it normally."},{"type":"Tongue","kind":"Ex","details":"A mobogo's tongue is a primary attack with reach equal to three times the mobogo's normal reach (45 ft. for a typical mobogo). A mobogo doesn't gain the grappled condition when using its tongue to grapple a foe."},{"type":"Vile Croak","kind":"Su","details":"As a standard action once every 1d4 rounds, a mobogo can unleash a thunderous croak. Any non-boggard or non-mobogo within 50 ft. of the mobogo must make a DC 19 Will save or become staggered for 1d4 rounds. Once a creature makes its saving throw against a particular mobogo's vile croak, it is immune to that mobogo's croak for 24 hours. Any boggards or mobogos within the area of a mobogo's vile croak gains a +2 morale bonus on attack rolls and saving throws against fear effects for 1 round. The save DC is Charisma-based."}],"description":"Huge and hungry, mobogos merge the features of gigantic toads and swampy dragons, and lair in the deepest, oldest swamps. Here, whole tribes of boggards serve the beasts' fickle, capricious whims.\n\nMobogos reside in the most primal swamps of the world, grotesque eldritch wildernesses unchanged for centuries. Boggards believe that in ancient times, after their fecund demon goddess deposited her frogspawn in the muddy morass of the world's still-forming continents, mobogos were among the first creatures to emerge. Ever since, the mobogos have slept and fed, preying upon the beasts of their fetid meres, growing huge and lethargic, and dreaming inscrutable amphibious dreams of their godly mother's return. Nearly all mobogos are attended by tribes of boggards. Mobogos care little for matters of origins and philosophies-they care only for the endless sacrifices of food, victims, and pleasing swamp art brought to them by their obedient tribes.\n\nA mobogo is 18 ft. tall and weighs 12,000 pounds.","ecology":"","habitat_society":""},{"name":"Movanic Deva","cr":10,"xp":9600,"alignment":"NG","size":"Medium","type":"outsider","subtypes":["angel","extraplanar","good"],"init":7,"senses":[{"type":"darkvision","modifier":"60 ft."},{"type":"detect evil"},{"type":"low-light vision"}],"auras":["protective aura"],"ac":24,"ac_touch":13,"ac_flat_footed":21,"ac_mods":"+3 Dex, +11 natural | +4 deflection vs. evil","hp":126,"hd":"12d10+60","hdvalue":12,"fort":12,"ref":11,"will":9,"save_mods":"+4 vs. poison, +4 vs. evil","defensive_abilities":["nature's pacifism","protected life force"],"dr":"10/ evil","immunities":["acid","cold","electricity","fire","death effects","energy drain","petrification"],"sr":21,"speed":[{"type":"land","speed":40},{"type":"fly","speed":60,"maneuverability":"good"}],"melee":"+1 flaming greatsword +17 (2d6+7/19-20 plus 1d6 fire)","space":"5 ft.","reach":"5 ft.","spell_like_abilities_caster_level":8,"spell_like_abilities_concentration":12,"spell_like_abilities":[{"frequency":"constant","spells":[{"spell":"detect evil"}]},{"frequency":"at-will","spells":[{"spell":"aid"},{"spell":"discern lies"},{"spell":"dispel evil"},{"spell":"dispel magic"},{"spell":"holy smite"},{"spell":"invisibility","details":"self only"},{"spell":"plane shift"},{"spell":"remove curse"},{"spell":"remove disease"},{"spell":"remove fear"}]},{"frequency":"1/day","spells":[{"spell":"antimagic field"},{"spell":"awaken"},{"spell":"holy aura"}]},{"frequency":"7/day","spells":[{"spell":"cure serious wounds"}]}],"strength":19,"dexterity":17,"constitution":18,"intelligence":17,"wisdom":17,"charisma":19,"baseatk":12,"cmb":16,"cmd":29,"feats":[{"feat":"Cleave"},{"feat":"Improved Initiative"},{"feat":"Iron Will"},{"feat":"Power Attack"},{"feat":"Toughness"},{"feat":"Vital Strike"}],"skills":[{"skill":"Diplomacy","value":19},{"skill":"Fly","value":22},{"skill":"Intimidate","value":19},{"skill":"Knowledge (planes)","value":18},{"skill":"Knowledge (religion)","value":18},{"skill":"Perception","value":26},{"skill":"Sense Motive","value":22},{"skill":"Stealth","value":18},{"skill":"Survival","value":18}],"languages":["Celestial","Draconic","Infernal","truespeech"],"environments":["any good-aligned plane"],"organizations":["solitary","pair","squad (3-6)"],"treasure":"double (+1 flaming greatsword)","description_visual":"This angel is all sharp lines and angles, muscular but lean, with large wings and a mighty flaming greatsword.","group":"Angel","source":"PFRPG Bestiary 2","special_abilities":[{"type":"Nature's Pacifism","kind":"Ex","details":"Animals and plant creatures don't willingly attack a movanic deva, though they can be forced to do so by magic. If the deva attacks a plant or animal, its protection against that creature ends."},{"type":"Protected Life Force","kind":"Ex","details":"Movanic devas are never harmed by positive-dominant or negative-dominant planar traits."}],"description":"Movanic devas serve as infantry in the celestial armies, though they spend most of their time patrolling the Positive, Negative, and Material Planes. On the Positive Plane, they watch over wandering good souls, which sometimes puts them into conf lict with the jyoti. On the Negative Plane, they battle undead, the sceaduinar, and the other strange things that hunt in the hungry void. Their rare visits to the Material Plane are usually to help powerful mortals when a great menace threatens to plunge an entire realm into evil.","ecology":"","habitat_society":"","gear":"+1 flaming greatsword"},{"name":"Mummy Lord","cr":10,"xp":9600,"race":"Human","classes":[{"class":"cleric of Set","level":9}],"alignment":"LE","size":"Medium","type":"undead","subtypes":["human"],"init":2,"senses":[{"type":"darkvision","modifier":"60 ft."}],"auras":["great despair (30 ft., DC 19)"],"ac":18,"ac_touch":14,"ac_flat_footed":15,"ac_mods":"+1 deflection, +2 Dex, +1 dodge, +4 natural","hp":107,"hd":"9d8+63","hdvalue":9,"fort":11,"ref":7,"will":11,"defensive_abilities":["channel resistance +4","undying will"],"dr":"10/-","immunities":["cold","electricity","undead traits"],"speed":[{"type":"land","speed":30}],"space":"5 ft.","reach":"5 ft.","special_attacks":[{"type":"channel negative energy","details":"8/day, DC 21, 5d6"},{"type":"channel rot"},{"type":"insidious mummy rot","details":"DC 19"},{"type":"sandstorm wrath","details":"DC 19, 6d8 fire and slashing"},{"type":"scythe of evil","details":"1/day, 4 rounds"},{"type":"undead mastery","details":"DC 19"}],"spell_like_abilities_caster_level":9,"spell_like_abilities_concentration":13,"spell_like_abilities":[{"frequency":"8/day","spells":[{"spell":"touch of darkness","details":"4 rounds"},{"spell":"touch of evil","details":"4 rounds"}]}],"spellsprepared_caster":"cleric","spellsprepared_caster_level":9,"spellsprepared_concentration":13,"spellsprepared":[{"spell_level":5,"spell_slots":1,"spells":[{"spell":"dispel good","type":"domain"},{"spell":"greater contagion"},{"spell":"slay living"}]},{"spell_level":4,"spell_slots":1,"spells":[{"spell":"divine power"},{"spell":"poison"},{"spell":"shadow conjuration","type":"domain"},{"spell":"spit venom"}]},{"spell_level":3,"spell_slots":1,"spells":[{"spell":"animate dead"},{"spell":"bestow curse"},{"spell":"deeper darkness","type":"domain"},{"spell":"magic vestment"},{"spell":"sands of time"}]},{"spell_level":2,"spell_slots":1,"spells":[{"spell":"align weapon","type":"domain"},{"spell":"bull's strength"},{"spell":"desecrate"},{"spell":"dread bolt"},{"spell":"hold person"},{"spell":"silence"}]},{"spell_level":1,"spell_slots":1,"spells":[{"spell":"bane"},{"spell":"cause fear"},{"spell":"command"},{"spell":"detect good"},{"spell":"divine favor"},{"spell":"protection from good","type":"domain"},{"spell":"sanctuary"}]},{"spell_level":0,"spell_slots":99,"spells":[{"spell":"detect magic"},{"spell":"guidance"},{"spell":"read magic"},{"spell":"resistance"}]}],"spelldomains":"Darkness, Evil","strength":20,"dexterity":14,"intelligence":10,"wisdom":20,"charisma":20,"baseatk":6,"cmb":11,"cmd":25,"feats":[{"feat":"Blind-Fight"},{"feat":"Combat Casting"},{"feat":"Dodge"},{"feat":"Improved Channel"},{"feat":"Lightning Reflexes"},{"feat":"Spell Focus (enchantment)"},{"feat":"Spell Focus (necromancy)"},{"feat":"Toughness","type":"bonus"}],"skills":[{"skill":"Intimidate","value":17},{"skill":"Knowledge (religion)","value":12},{"skill":"Sense Motive","value":20},{"skill":"Spellcraft","value":12},{"skill":"Stealth","value":17}],"languages":["Ancient Osiriani","Common"],"sq":[{"type":"eyes of darkness","details":"4 rounds/day"}],"environments":["any (Osirion)"],"organizations":["solitary","court (mummy lord and 6-14 standard mummies or mummified creatures)"],"treasure":"none","description_visual":"Dirty linen strips swathe this emaciated figure from head to toe, and its stripped headdress marks it as a once-noble being, whose eyes now burn with an unholy light.","source":"AP 84","description":"Mummification is a practice common to many cultures, although the use of magical techniques to imbue the departed with potent, undead vitality is less widespread. On rare occasions, if the deceased was a person of great rank and exceeding malice, he may undergo even more elaborate and expensive rituals granting him greater power in undeath, and he eventually rises from his tomb as a mummy lord. Retaining the powers and abilities he had in life, he becomes a creature consumed by the desire to dominate others and a seething envy for the living that drives him to acts of surpassing cruelty.","ecology":"","habitat_society":"","gear":"scroll of spiritual weapon, scroll of summon monster III; Other Gear +1 spear, headband of inspired wisdom +2, ring of protection +1"},{"name":"Myrmecoleon","cr":10,"xp":9600,"alignment":"N","size":"Huge","type":"magical beast","subtypes":["mythic"],"init":-2,"senses":[{"type":"darkvision","modifier":"60 ft."},{"type":"low-light vision"}],"ac":24,"ac_touch":6,"ac_flat_footed":24,"ac_mods":"-2 Dex, +18 natural, -2 size","hp":135,"hd":"10d10+80","hdvalue":10,"fort":12,"ref":7,"will":4,"defensive_abilities":["ferocity"],"dr":"5/epic","immunities":["acid"],"speed":[{"type":"land","speed":30},{"type":"burrow","speed":20},{"type":"climb","speed":20}],"melee":"mandibles +14 (4d8+9/19-20 plus grab)","space":"15 ft.","reach":"15 ft.","special_attacks":[{"type":"blood drain","details":"1d2 Con"},{"type":"constrict","details":"4d8+9"},{"type":"death throes"},{"type":"mythic power","details":"3/day, surge +1d6"},{"type":"scalding spray"},{"type":"trample","details":"2d8+9, DC 21"}],"strength":23,"dexterity":6,"constitution":20,"intelligence":2,"wisdom":13,"charisma":5,"baseatk":10,"cmb":18,"cmb_special":"+4 vs. grapple","cmd":24,"cmd_special":"+4 vs. grapple, +8 vs. trip","feats":[{"feat":"Improved Critical (mandibles)"},{"feat":"Lightning Reflexes"},{"feat":"Power Attack","type":"mythic"},{"feat":"Shatter Defenses"},{"feat":"Weapon FocusM (mandibles)"}],"skills":[{"skill":"Climb","value":22},{"skill":"Perception","value":9}],"environments":["temperate hills","temperate plains"],"organizations":["solitary"],"treasure":"none","description_visual":"This towering beetle-like horror has thick carapace segments and massive mandibles that leak sizzling acid.","source":"PFRPG Bestiary 4","special_abilities":[{"type":"Death Throes","kind":"Ex","details":"When a myrmecoleon is slain, its body explodes, releasing the acids that churn within it. All creatures within a 20-foot-radius burst take 4d8 acid damage (Reflex DC 20 half). The save DC is Constitution-based."},{"type":"Scalding Spray","kind":"Ex","details":"Once every 1d4 rounds, a myrmecoleon can eject a 60-foot cone of acidic chemicals from its mouth. Creatures caught in the blast take 8d6 points of acid damage and are blinded for 10 minutes (Reflex DC 20 half damage and negates blindness). Following the initial blast, the chemicals vaporize into a thick and noxious cloud 20 ft. high with a 40-foot radius. Within the cloud, all sight is obscured beyond 5 ft. Furthermore, any living creature within the area of effect must succeed at a DC 20 Fortitude save or become nauseated for as long as it remains in the cloud and for 1d4+1 rounds after it leaves the cloud. Any creature that succeeds at its save but remains in the cloud must continue to save each round on the myrmecoleon's turn. This is a poison effect. The save DCs for this ability are Constitution-based."}],"description":"This monstrous, insectlike beast resembles a huge beetle with gleaming black armored plates. Around its head and neck the chitin forms a great mane of jagged spikes. Its insides swirl with acidic juices. Myrmecoleons live in remote areas where they claim large territories of wilderness as their hunting grounds. They're often drawn to far-f lung ancient ruins and sites of mythic power, and sometimes act as guardians of such places. This has led some sages to theorize that some myrmecoleons aren't born but are spontaneously created by sites thrumming with mythic power. These creatures only rarely interact with others of their kind-and these interactions usually end in brutal and destructive death matches. Myrmecoleons are cannibals and readily eat those they defeat. When fighting, these insects put on great displays to intimidate rivals or other threats. Myrmecoleons are known to roll in the corpses of their prey, impaling the bodies upon their carapaces and leaving them there to rot. Why they perform this gruesome act remains unknown. Those who have studied the creature to understand its r u d ime nt a r y i nt e l l i g enc e hypothesize that it might be some sort of a display to showcase its strength to others of its kind, or even be one part of an elaborate mating ritual.","ecology":"","habitat_society":""},{"name":"Mythic Sphinx","cr":10,"xp":9600,"alignment":"N","size":"Large","type":"magical beast","subtypes":["mythic"],"init":5,"senses":[{"type":"darkvision","modifier":"60 ft."},{"type":"detect magic"},{"type":"low-light vision"},{"type":"see invisibility"}],"ac":25,"ac_touch":10,"ac_flat_footed":24,"ac_mods":"+1 Dex, +15 natural, -1 size","hp":142,"hd":"12d10+76","hdvalue":12,"fort":11,"ref":9,"will":10,"dr":"10/epic","resists":[{"type":"electricity","value":30},{"type":"fire","value":30}],"sr":21,"speed":[{"type":"land","speed":40},{"type":"fly","speed":60,"maneuverability":"poor"}],"melee":"2 claws +18 (2d8+7/18-20)","space":"10 ft.","reach":"5 ft.","special_attacks":[{"type":"mythic power","details":"4/day, surge +1d8"},{"type":"pounce"},{"type":"rake","details":"2 claws +18, 2d8+7/18-20"},{"type":"riddle"},{"type":"sphinx's curse"}],"spell_like_abilities_caster_level":12,"spell_like_abilities_concentration":19,"spell_like_abilities":[{"frequency":"constant","spells":[{"spell":"comprehend languages"},{"spell":"detect magic"},{"spell":"read magic"},{"spell":"see invisibility"},{"spell":"tongues"}]},{"frequency":"at-will","spells":[{"spell":"statue","details":"self only"}]},{"frequency":"1/day","spells":[{"spell":"greater dispel magic"},{"spell":"legend lore"},{"spell":"locate object"},{"spell":"remove curse"}]},{"frequency":"3/day","spells":[{"spell":"clairaudience/clairvoyance"},{"spell":"feeblemind"}]},{"frequency":"1/week","spells":[{"spell":"symbol of fear","details":"any one of the following"},{"spell":"symbol of pain"},{"spell":"symbol of persuasion"},{"spell":"symbol of sleep"},{"spell":"symbol of stunning","details":"all symbols last for 1 week maximum"}]}],"strength":24,"dexterity":13,"constitution":16,"intelligence":18,"wisdom":19,"charisma":21,"baseatk":12,"cmb":20,"cmd":31,"cmd_special":"+4 vs. trip","feats":[{"feat":"Alertness"},{"feat":"Combat Casting"},{"feat":"Hover"},{"feat":"Improved Critical (claws)","type":"mythic"},{"feat":"Improved Initiative"},{"feat":"Iron Will","type":"mythic"}],"skills":[{"skill":"Bluff","value":15},{"skill":"Diplomacy","value":15},{"skill":"Fly","value":7},{"skill":"Intimidate","value":15},{"skill":"Knowledge (any two)","value":6},{"skill":"Perception","value":21},{"skill":"Sense Motive","value":19},{"skill":"Spellcraft","value":12}],"languages":["Common","Draconic","Sphinx","comprehend languages","read magic","tongues"],"environments":["warm deserts","warm hills"],"organizations":["solitary","pair","cult (3-6)"],"treasure":"double","description_visual":"This woman has the upper body of a human queen, the lower body of a lion, a snake-headed tail, and great eagle wings.","group":"Sphinx","source":"Mythic Adventures","special_abilities":[{"type":"Riddle","kind":"Su","details":"A mythic sphinx can expend one use of mythic power to ask a riddle of up to 12 creatures within 100 ft. Each creature is compelled (Will DC 21 negates) to give an answer within 1 minute (creatures in combat when the sphinx uses this ability gain a +4 bonus on the saving throw). The sphinx gets a +4 bonus on attack rolls, damage rolls, and saving throws against any creature that refuses to answer (via a successful saving throw), can't answer (including if it's in an area of silence), answers incorrectly, or flees the sphinx instead of answering. The bonuses from failing to solve the riddle last for 24 hours. The need to answer is a compulsion, mind-affecting, language-dependent enchantment effect. The save DC is Charisma-based."},{"type":"Sphinx's Curse","kind":"Su","details":"A mythic sphinx can expend one use of mythic power when it damages an opponent with a claw attack to curse its opponent with bleeding wounds (Will DC 21 negates). Whenever a cursed target takes piercing or slashing damage, it takes 1d6 points of bleed damage every round for the next 1d6 rounds. This bleed damage stacks with itself and with all other bleed effects. A creature that strikes the killing blow against a mythic sphinx must succeed at a saving throw or become cursed (this requires no uses of mythic power from the sphinx). The save DC is Charisma-based."}],"description":"A mythic sphinx is often given a task by a deity, such as watching over a city, testing a great mortal hero, or guarding an artifact. She is gifted with magic to compel obedience and curse those who would defy her commands or interfere with her task.","ecology":"","habitat_society":""},{"name":"Mythic Treant","cr":10,"xp":9600,"alignment":"NG","size":"Huge","type":"plant","subtypes":["mythic"],"init":-1,"senses":[{"type":"low-light vision"}],"ac":25,"ac_touch":7,"ac_flat_footed":25,"ac_mods":"-1 Dex, +18 natural, -2 size","hp":146,"hd":"12d8+92","hdvalue":12,"fort":13,"ref":3,"will":10,"dr":"10/epic and slashing","immunities":["plant traits"],"weaknesses":["vulnerable to fire"],"speed":[{"type":"land","speed":30}],"melee":"2 slams +19 (3d6+10/18-20)","ranged":"rock +7 (2d6+15)","space":"15 ft.","reach":"15 ft.","special_attacks":[{"type":"mythic power","details":"4/day, surge +1d8"},{"type":"rock throwing","details":"180 ft."},{"type":"trample","details":"3d6+15, DC 26"},{"type":"druidic magic"}],"spell_like_abilities_caster_level":10,"spell_like_abilities_concentration":15,"spell_like_abilities":[{"frequency":"1/day","spells":[{"spell":"call lightning storm"}]},{"frequency":"3/day","spells":[{"spell":"cure serious wounds"},{"spell":"darkness"},{"spell":"rusting grasp"},{"spell":"shout"},{"spell":"summon nature's ally IV"}]},{"frequency":"7/day","spells":[{"spell":"animal messenger"},{"spell":"calm animals"},{"spell":"create water"},{"spell":"entangle"},{"spell":"magic fang"},{"spell":"neutralize poison"},{"spell":"quench"},{"spell":"sleep"},{"spell":"wind wall"},{"spell":"wood shape"}]}],"strength":31,"dexterity":8,"constitution":21,"intelligence":12,"wisdom":18,"charisma":13,"baseatk":9,"cmb":21,"cmb_special":"+2 vs. sunder","cmd":32,"cmd_special":"+2 vs. sunder","feats":[{"feat":"Alertness"},{"feat":"Improved Critical M (slam)"},{"feat":"Improved Sunder"},{"feat":"Iron Will"},{"feat":"Power Attack"},{"feat":"Weapon Focus M (slam)"}],"skills":[{"skill":"Diplomacy","value":9},{"skill":"Intimidate","value":9},{"skill":"Knowledge (nature)","value":9},{"skill":"Perception","value":17},{"skill":"Sense Motive","value":10},{"skill":"Stealth","value":-9,"special":"+7 in forests"}],"languages":["Common","Sylvan","Treant","treespeech"],"sq":[{"type":"animate trees"},{"type":"double damage against objects"},{"type":"drink deep"},{"type":"woodland stride"}],"environments":["any forests"],"organizations":["solitary","grove (2-7)"],"treasure":"standard","description_visual":"Standing upright and powerful, this mighty tree-person channels nature's fury into green energy in its gnarled hands.","group":"Treant","source":"Mythic Adventures","special_abilities":[{"type":"Animate Trees","kind":"Sp","details":"A mythic treant can animate and control up to two trees within 180 ft. at will. It takes 1 full round for a tree to uproot itself, after which it moves at a speed of 10 ft. and fights as a non-mythic treant. It has only one slam attack, lacks the treant's animation and rock-throwing abilities, and has the treant's vulnerability to fire. If the treant terminates the animation, moves out of range, or is incapacitated, the tree immediately takes root wherever it is and returns to its normal state. If the treant expends one use of mythic power when it animates a tree, the tree remains animated and under the treant's control up to a range of 1 mile, and it doesn't count toward the treant's limit of controlling up to two trees at a time."},{"type":"Double Damage Against Objects","kind":"Ex","details":"A mythic treant or animated tree that makes a full attack against an object or structure deals double damage."},{"type":"Drink Deep","kind":"Su","details":"A mythic treant can expend one use of mythic power to lose its vulnerability to fire for 1 hour."},{"type":"Treespeech","kind":"Ex","details":"A treant has the ability to converse with plants as if subject to a continual speak with plants spell, and most plants greet it with an attitude of friendly or helpful."},{"type":"Druidic Magic","kind":"Su","details":"A mythic treant can expend one use of mythic power to cast any druid spell of 3rd level or lower, or two uses of mythic power to cast any druid spell of 5th level or lower. Its caster level for this spell is 10th."}],"description":"A mythic treant is an ancient entity granted power by a deity or magical pool. They're the shepherds of forests, and even less likely to converse with short-lived races.","ecology":"","habitat_society":""},{"name":"Mythic Vampire","cr":10,"xp":9600,"race":"Human vampire","classes":[{"class":"fighter","level":7}],"alignment":"NE","size":"Medium","type":"undead","subtypes":["augmented humanoid","human","mythic"],"init":12,"init_special":"mythic","senses":[{"type":"darkvision","modifier":"60 ft."}],"ac":29,"ac_touch":16,"ac_flat_footed":24,"ac_mods":"+3 armor, +1 deflection, +4 Dex, +1 dodge, +10 natural","hp":117,"hd":"7d10+74","hdvalue":7,"hp_mods":["fast healing 5"],"fort":11,"ref":10,"will":4,"save_mods":"Will: +2 vs. fear","defensive_abilities":["bravery +2 channel resistance +8"],"dr":"10/epic and magic and silver","immunities":["undead traits"],"resists":[{"type":"cold","value":10},{"type":"electricity","value":10}],"weaknesses":["vampire weaknesses"],"speed":[{"type":"land","speed":30}],"melee":"+1 longsword +19 (1d8+12/19-20 plus energy drain), slam +15 (1d4+4 plus energy drain)","ranged":"mwk light crossbow +12 (1d8/19-20)","space":"5 ft.","reach":"5 ft.","special_attacks":[{"type":"blood drain"},{"type":"children of the night","details":"ghouls or shadows"},{"type":"create spawn"},{"type":"dominate","details":"DC 17"},{"type":"energy drain","details":"2 levels, DC 17"},{"type":"mythic power","details":"4/day, surge +1d8"},{"type":"negative energy focus"},{"type":"scabrous claws"},{"type":"weapon training","details":"heavy blades +1"}],"strength":26,"dexterity":18,"intelligence":14,"wisdom":10,"charisma":19,"baseatk":7,"cmb":15,"cmd":31,"feats":[{"feat":"Alertness","type":"bonus"},{"feat":"Combat Reflexes","type":"bonus"},{"feat":"Deceitful"},{"feat":"Disruptive","type":"mythic"},{"feat":"Dodge","type":"bonus"},{"feat":"Greater Weapon Focus (longsword)"},{"feat":"Improved Initiative","type":"bonus"},{"feat":"Improved Initiative","type":"mythic"},{"feat":"Lightning Reflexes","type":"bonus"},{"feat":"Mobility"},{"feat":"Power Attack"},{"feat":"Quick Draw"},{"feat":"Toughness","type":"bonus"},{"feat":"Vital Strike"},{"feat":"Weapon Focus (longsword)"},{"feat":"Weapon Specialization (longsword)"}],"skills":[{"skill":"Bluff","value":21},{"skill":"Climb","value":14},{"skill":"Disguise","value":6},{"skill":"Intimidate","value":14},{"skill":"Perception","value":17},{"skill":"Ride","value":8},{"skill":"Sense Motive","value":17},{"skill":"Stealth","value":15}],"languages":["Common","Draconic","Undercommon"],"sq":[{"type":"armor training","details":"2"},{"type":"change shape","details":"dire bat or wolf, beast shape II"},{"type":"gaseous form"},{"type":"overcome weakness","details":"garlic, sunlight"},{"type":"shadowless"},{"type":"spider climb"}],"environments":["any"],"organizations":["solitary","family (vampire plus 2-8 spawn)"],"treasure":"none","description_visual":"This aristocratic figure could easily pass for human if not for the grave-pale skin, red eyes, and long fangs.","group":"Vampire","source":"Mythic Adventures","description":"A mythic vampire has ties to the earliest of its kind, being either one of the first vampires or the offspring of such ancient creatures.","ecology":"","habitat_society":"","gear":"potion of inflict serious wounds, +1 bolts (10), +1 leather armor, +1 longsword, mwk light crossbow, cloak of resistance +2, ring of protection +1"},{"name":"Nereid","cr":10,"xp":9600,"alignment":"CN","size":"Medium","type":"fey","subtypes":["water"],"init":9,"senses":[{"type":"low-light vision"}],"auras":["beguiling aura (30 ft., DC 23)"],"ac":25,"ac_touch":25,"ac_flat_footed":15,"ac_mods":"+5 deflection, +9 Dex, +1 dodge","hp":126,"hd":"12d6+84","hdvalue":12,"fort":11,"ref":17,"will":14,"defensive_abilities":["transparency"],"dr":"10/cold iron","immunities":["cold","poison"],"sr":21,"weaknesses":["shawl"],"speed":[{"type":"land","speed":30},{"type":"swim","speed":60}],"melee":"touch +10 (poison)","ranged":"spray +15 touch (poison)","space":"5 ft.","reach":"5 ft.","special_attacks":[{"type":"drowning kiss"}],"spell_like_abilities_caster_level":12,"spell_like_abilities_concentration":19,"spell_like_abilities":[{"frequency":"at-will","spells":[{"spell":"control water"},{"spell":"suggestion","details":"only against creatures that are currently fascinated by her beguiling aura"}]},{"frequency":"1/day","spells":[{"spell":"summon monster VI","details":"water elementals only"}]}],"strength":11,"dexterity":29,"constitution":24,"intelligence":14,"wisdom":22,"charisma":21,"baseatk":6,"cmb":15,"cmd":37,"feats":[{"feat":"Ability Focus (beguiling aura)"},{"feat":"Agile Maneuvers"},{"feat":"Defensive Combat Training"},{"feat":"Dodge"},{"feat":"Mobility"},{"feat":"Weapon Finesse"}],"skills":[{"skill":"Bluff","value":20},{"skill":"Escape Artist","value":24},{"skill":"Knowledge (nature)","value":17},{"skill":"Perception","value":21},{"skill":"Perform (sing)","value":20},{"skill":"Sense Motive","value":21},{"skill":"Stealth","value":24},{"skill":"Swim","value":23}],"languages":["Aquan","Common","Sylvan"],"sq":[{"type":"change shape","details":"Medium water elemental, elemental body II"},{"type":"unearthly grace"}],"environments":["any aquatic"],"organizations":["solitary","troupe (1 nereid plus 1 giant squid, 1 giant octopus, 1 giant moray eel, or an orca)"],"treasure":"standard","description_visual":"This beautiful woman has pearlescent skin and long, dark hair. Her nudity is barely hidden by a diaphanous, wet shawl.","source":"PFRPG Bestiary 2","special_abilities":[{"type":"Beguiling Aura","kind":"Su","details":"Any creature sexually attracted to women runs the risk of being beguiled by a nereid if it looks upon her beauty from a distance of 30 ft. or less. If the creature fails a DC 23 Will save, it is immediately fascinated. A nereid may use her suggestion spell-like ability at will against creatures that are fascinated by her beguiling aura. This is a mind-affecting compulsion effect. The save DC is Charisma-based."},{"type":"Drowning Kiss","kind":"Su","details":"A nereid can flood the lungs of a willing, helpless, or fascinated creature by touching it (traditionally by kissing the creature on the lips). If the target cannot breathe water, it cannot hold its breath and immediately begins to drown. On its turn, the target can attempt a DC 23 Fortitude save to cough up this water; otherwise it falls unconscious at 0 hp. On the next round, the target must save again or drop to -1 hit points and be dying; on the third round it must save again or die. The save DC is Constitution-based."},{"type":"Poison","kind":"Ex","details":"Touch or spray (range 30 ft.)-contact; save Fort DC 23; frequency 1/round for 6 rounds; effect 1d2 Con plus blindness; cure 2 consecutive saves."},{"type":"Shawl","kind":"Ex","details":"A nereid's shawl (hardness 2, hp 6) contains a portion of her life force. If the shawl is ever destroyed, the nereid takes 1d6 points of Constitution drain per hour until she dies. A nereid can craft a new shawl from water by making a DC 25 Will save, but each attempt takes 1d4 hours to complete. Attempts to destroy or steal a nereid's shawl require the sunder or disarm attempts."},{"type":"Transparency","kind":"Su","details":"When underwater, a nereid's body becomes transparent, effectively rendering her invisible. She can become visible or transparent at will as a free action."},{"type":"Unearthly Grace","kind":"Su","details":"A nereid adds her Charisma bonus as a deflection bonus to her Armor Class and CMD if she wears no armor."}],"description":"Nereids are capricious and often dangerous aquatic fey that appear as strikingly beautiful women, often seen bathing unclothed in the water. Many sailors have met their doom following a nereid, for though a nereid's beauty is otherworldly, her watery kiss is death. Others seek out nereids, for if one can secure control over the creature's shawl, the cloth can be used to force the nereid's compliance. A nereid forced to obey in this manner immediately attempts to slay her master as soon as she can secure her shawl's safety.","ecology":"","habitat_society":""},{"name":"Noble Efreeti","cr":10,"xp":9600,"alignment":"LE","size":"Large","type":"outsider","subtypes":["extraplanar","fire"],"init":7,"senses":[{"type":"darkvision","modifier":"60 ft."},{"type":"detect magic"}],"ac":28,"ac_touch":13,"ac_flat_footed":24,"ac_mods":"+7 armor, +3 Dex, +1 dodge, +8 natural, -1 size","hp":136,"hd":"13d10+65","hdvalue":13,"fort":8,"ref":11,"will":10,"immunities":["fire"],"weaknesses":["vulnerability to cold"],"speed":[{"type":"land","speed":20},{"type":"fly","speed":40,"maneuverability":"perfect"}],"melee":"2 slams +18 (1d8+6 plus 1d6 fire)","space":"10 ft.","reach":"10 ft.","special_attacks":[{"type":"change size"},{"type":"heat"}],"spell_like_abilities_caster_level":15,"spell_like_abilities_concentration":23,"spell_like_abilities":[{"frequency":"constant","spells":[{"spell":"detect magic"}]},{"frequency":"at-will","spells":[{"spell":"plane shift","details":"wills targets to elemental planes, Astral Plane, or Material Plane only"},{"spell":"produce flame"},{"spell":"pyrotechnics"},{"spell":"scorching ray"}]},{"frequency":"1/day","spells":[{"spell":"gaseous form"},{"spell":"grant up to 3 wishes","details":"to non-genies only"},{"spell":"greater invisibility"},{"spell":"permanent image"},{"spell":"pyroclastic storm","details":"as ice storm, with fire instead of cold damage"}]},{"frequency":"3/day","spells":[{"spell":"fireball"},{"spell":"heat metal"},{"spell":"invisibility"},{"spell":"quickened scorching ray"},{"spell":"wall of fire"}]}],"strength":23,"dexterity":17,"constitution":18,"intelligence":12,"wisdom":14,"charisma":15,"baseatk":13,"cmb":20,"cmd":34,"feats":[{"feat":"Combat Casting"},{"feat":"Combat Reflexes"},{"feat":"Deceitful"},{"feat":"Dodge"},{"feat":"Improved Initiative"},{"feat":"Power Attack"},{"feat":"Quicken Spell-Like Ability (scorching ray)"},{"feat":"Toughness"}],"skills":[{"skill":"Bluff","value":22},{"skill":"Craft (armor)","value":17},{"skill":"Disguise","value":13},{"skill":"Fly","value":10},{"skill":"Intimidate","value":15},{"skill":"Perception","value":18},{"skill":"Sense Motive","value":18},{"skill":"Spellcraft","value":17},{"skill":"Stealth","value":8}],"languages":["Aquan","Auran","Common","Ignan","Terran","telepathy 100 ft."],"sq":[{"type":"change shape","details":"humanoid or giant, alter self or giant form I"}],"environments":["any (Plane of Fire)"],"organizations":["solitary","pair","company (3-6)","band (7-12)"],"treasure":"standard (mwk falchion, other gear)","description_visual":"This muscular giant has crimson skin, smoldering eyes, and small black horns. Smoke rises in curls from its flesh.","group":"Malik","source":"PFRPG Bestiary","special_abilities":[{"type":"Change Size","kind":"Sp","details":"Twice per day, a noble efreeti can magically change a creature's size. This works just like an enlarge person or reduce person spell (the efreeti chooses when using the ability), except that the ability can work on the efreeti. A DC 13 Fortitude save negates the effect. The save DC is Charisma-based. This is the equivalent of a 2nd-level spell."},{"type":"Heat","kind":"Ex","details":"An noble efreeti's body deals 1d6 points of fire damage whenever it hits in melee, or in each round it grapples."}],"description":"The efreet (singular efreeti) are genies from the Plane of Fire. An efreeti stands about 12 ft. tall and weighs about 2,000 pounds.\n\nEfreet have few allies among geniekind. They certainly hate djinn, and attack them on sight. They hold an equally strong enmity for marids, and view the jann as frail and weak. Efreet often work closely with shaitans, yet even then alliances are temporary at best.","ecology":"","habitat_society":"","gear":"+3 chain shirt, dimensional shackles, iron key radiating a faint transmutation aura and engraved with a cross-eyed medusa head"},{"name":"Nosferatu","cr":10,"xp":9600,"race":"Human","classes":[{"class":"rogue","level":9}],"alignment":"NE","size":"Medium","type":"undead","subtypes":["augmented humanoid","human"],"init":11,"senses":[{"type":"darkvision","modifier":"60 ft."},{"type":"low-light vision"},{"type":"scent"}],"ac":30,"ac_touch":18,"ac_flat_footed":23,"ac_mods":"+4 armor, +1 deflection, +6 Dex, +1 dodge, +8 natural","hp":71,"hd":"9d8+27","hdvalue":9,"hp_mods":["fast healing 5"],"fort":7,"ref":16,"will":7,"save_mods":"+3 vs. traps","defensive_abilities":["channel resistance +4","evasion","improved uncanny dodge","trap sense +3"],"dr":"5/wood and piercing","immunities":["undead traits"],"resists":[{"type":"cold","value":10},{"type":"electricity","value":10},{"type":"sonic","value":10}],"weaknesses":["vampire weaknesses"],"speed":[{"type":"land","speed":30}],"melee":"2 claws +14 (1d6+3)","space":"5 ft.","reach":"5 ft.","special_attacks":[{"type":"blood drain","details":"1d4 Con and 1d4 Wis"},{"type":"dominate","details":"DC 17"},{"type":"sneak attack","details":"+5d6"},{"type":"telekinesis","details":"DC 17"}],"strength":16,"dexterity":24,"intelligence":16,"wisdom":16,"charisma":16,"baseatk":6,"cmb":9,"cmd":28,"feats":[{"feat":"Alertness","type":"bonus"},{"feat":"Dodge"},{"feat":"Improved Initiative","type":"bonus"},{"feat":"Lightning Reflexes","type":"bonus"},{"feat":"Mobility"},{"feat":"Power Attack"},{"feat":"Skill FocusB (Perception)"},{"feat":"Skill FocusB (Stealth)"},{"feat":"Spring Attack"},{"feat":"Weapon Finesse"},{"feat":"Weapon Focus (claw)"}],"skills":[{"skill":"Acrobatics","value":19},{"skill":"Bluff","value":15},{"skill":"Climb","value":15},{"skill":"Intimidate","value":15},{"skill":"Knowledge (dungeoneering)","value":15},{"skill":"Knowledge (history)","value":12},{"skill":"Knowledge (local)","value":15},{"skill":"Knowledge (religion)","value":12},{"skill":"Perception","value":28},{"skill":"Sense Motive","value":13},{"skill":"Stealth","value":30},{"skill":"Survival","value":12},{"skill":"Swim","value":15},{"skill":"Use Magic Device","value":15}],"languages":["Aklo","Common","telepathy 60 ft."],"sq":[{"type":"rogue talents","details":"bleeding attack +5, fast stealth, stand up, surprise attack"},{"type":"spider climb"},{"type":"swarm form"},{"type":"trapfinding","details":"+4"}],"environments":["any ruins","any urban"],"organizations":["solitary"],"treasure":"none","description_visual":"This somberly dressed but feral-looking gaunt man has yellowed, ratlike fangs and ragged, clawed fingers.","group":"Vampire","source":"PFRPG Bestiary 4","description":"Nosferatu are savage undead who may be the progenitors of the common, more refined vampires. The curse of the nosferatu lacks the elegance and romance of its modern form, harkening to a forgotten age of verminous hunger and eerie powers. Granted immortal life but not immortal youth, nosferatu are withered, embittered creatures unable to create others of their kind, as they somehow lost that ability long ago. Their ancient sensibilities still ref lect the cruelty of epochs past, and their age-spanning plots are untethered by the modern aff liction of morality. Nosferatu resent common vampires (which they call \"moroi,\" an ancient term from a lost language) for their beauty, whereas those vampires scorn the nosferatu as bestial relics of an earlier age, best hidden away in remote ruins so as not to sully the charismatic reputation of \"true\" vampires. Because nosferatu can't create spawn, any nosferatu in existence are very old-created long ago in a time before they lost the ability to infect others with their undead curse. Most nosferatu live in isolated places with few visitors, and a nosferatu could be a thousand years old and yet have fewer than a dozen character levels because it lacks sufficient foes to challenge it or the initiative to train itself.","ecology":"","habitat_society":"","gear":"wand of scorching ray [10 charges], +2 leather armor, belt of incredible dexterity +2, cloak of resistance +1, ring of protection +1"},{"name":"Nue","cr":10,"xp":9600,"alignment":"NE","size":"Large","type":"magical beast","init":9,"senses":[{"type":"darkvision","modifier":"60 ft."},{"type":"low-light vision"}],"ac":24,"ac_touch":15,"ac_flat_footed":18,"ac_mods":"+5 Dex, +1 dodge, +9 natural, -1 size","hp":126,"hd":"12d10+60","hdvalue":12,"fort":13,"ref":13,"will":7,"speed":[{"type":"land","speed":30}],"melee":"bite +17 (2d6+6 plus energy drain), bite +17 (1d4+6 plus poison), 2 claws +17 (1d6+6)","space":"10 ft.","reach":"10 ft.","special_attacks":[{"type":"energy drain","details":"2 levels, DC 16"},{"type":"pounce"}],"spell_like_abilities_caster_level":12,"spell_like_abilities_concentration":21,"spell_like_abilities":[{"frequency":"1/day","spells":[{"spell":"nightmare"},{"spell":"shout"},{"spell":"waves of fatigue"}]},{"frequency":"3/day","spells":[{"spell":"contagion"},{"spell":"hold person"}]}],"strength":22,"dexterity":21,"constitution":20,"intelligence":7,"wisdom":17,"charisma":10,"baseatk":12,"cmb":19,"cmd":35,"cmd_special":"+4 vs. trip","feats":[{"feat":"Combat Casting"},{"feat":"Combat Reflexes"},{"feat":"Dodge"},{"feat":"Improved Initiative"},{"feat":"Mobility"},{"feat":"Skill Focus (Stealth)"}],"skills":[{"skill":"Climb","value":13},{"skill":"Perception","value":10},{"skill":"Stealth","value":11}],"languages":["Common"],"sq":[{"type":"cloud form"}],"environments":["warm forests","warm mountains"],"organizations":["solitary","pair","ambush (3-6)"],"treasure":"standard","description_visual":"Materializing out of a noxious black cloud, this beast has the head of a fanged monkey and the body of a tiger with a viper as a tail.","source":"PFRPG Bestiary 3","special_abilities":[{"type":"Cloud Form","kind":"Su","details":"A nue can change into the form of a 10-foot black cloud or back to its normal form as a standard action. A nue in cloud form is otherwise treated as if under the effects of gaseous form, except that it obscures vision like fog cloud."},{"type":"Poison","kind":"Ex","details":"Bite-injury; save Fort DC 21; frequency 1/round for 6 rounds; effect 1d4 Strength damage; cure 2 consecutive saves. The save DC is Constitution-based."}],"description":"This strange creature has the body of a tiger, the head of a fanged monkey, and a poisonous viper for a tail. Though some call it a chimera and treat it as an exotic specimen of that creature, it is a completely different breed of beast.\n\nIntelligent enough to enjoy cruelty as well as inf licting terror upon its prey, a nue delights in toying with its victim before dealing the killing blow. Often, a nue will select a target and plague it with nightmares before it even attempts an act of violence, wearing down the victim with dreadful dreams and phantasmagoric terrors. Once its prey is thoroughly exhausted, the nue will finally steal into the victim's sleeping chambers and engage in combat, paralyzing its target with its magic and infecting its prey with both disease and poison, letting the victim writhe in pain before succumbing to death.\n\nA nue's ghastly appearance in physical form is only made eerier by its ability to turn into an inky cloud of darkness. In this guise, a nue can hide amongst fog clouds or shadows before emerging as the destructive horror it is. By the time a nue crawls forth from the inscrutable black cloud, its prey is often too fatigued from its strange night terrors to defend itself. The dreams a nue impregnates creatures' minds with varies from victim to victim, but all share the trait of an ever-present, foreboding cloud that exudes a fierce and palpable sense of malice.\n\nSome legends suggest that nues are the spirits of children warped into twisted forms to spread paranoia, exhaustion, and fear among former friends and family. According to these stories, such a cursed child wreaks terror upon its friends and relatives until they are all either dead or driven mad by fear. Then, the creature moves on, seeking more challenging kills to sate its vicious hunger. The greatest joy a nue can feel is snuffing the life of a once-strong and proud target that has been brought low by its debilitating attacks.\n\nA nue is 9 ft. long and weighs 600 pounds.","ecology":"","habitat_society":""},{"name":"Nyogoth","cr":10,"xp":9600,"alignment":"CE","size":"Medium","type":"outsider","subtypes":["chaotic","evil","extraplanar","qlippoth"],"init":5,"senses":[{"type":"darkvision","modifier":"60 ft."}],"ac":24,"ac_touch":15,"ac_flat_footed":19,"ac_mods":"+5 Dex, +9 natural","hp":125,"hd":"10d10+70","hdvalue":10,"fort":14,"ref":12,"will":7,"defensive_abilities":["acid spray"],"dr":"10/lawful","immunities":["acid","cold","poison","mind-affecting effects"],"resists":[{"type":"electricity","value":10},{"type":"fire","value":10}],"speed":[{"type":"land","speed":5},{"type":"fly","speed":30,"maneuverability":"good"}],"melee":"4 bites +15 (1d6+3/19-20 plus 1d4 acid), bite +15 (2d6+3/19-20 plus 1d4 acid)","space":"5 ft.","reach":"5 ft.","special_attacks":[{"type":"horrific appearance","details":"DC 18"}],"spell_like_abilities_caster_level":10,"spell_like_abilities_concentration":17,"spell_like_abilities":[{"frequency":"at-will","spells":[{"spell":"acid arrow"}]},{"frequency":"1/day","spells":[{"spell":"acid fog"},{"spell":"dimension door"}]},{"frequency":"7/day","spells":[{"spell":"fear"},{"spell":"protection from law"}]}],"strength":16,"dexterity":21,"constitution":24,"intelligence":9,"wisdom":19,"charisma":16,"baseatk":10,"cmb":13,"cmd":28,"cmd_special":"can't be tripped","feats":[{"feat":"Combat Reflexes"},{"feat":"Improved Critical (bite)"},{"feat":"Power Attack"},{"feat":"Vital Strike"},{"feat":"Weapon Finesse"}],"skills":[{"skill":"Fly","value":22},{"skill":"Intimidate","value":16},{"skill":"Knowledge (planes)","value":12},{"skill":"Perception","value":17},{"skill":"Stealth","value":18}],"languages":["Abyssal","telepathy 100 ft."],"sq":[{"type":"flight"}],"environments":["any (Abyss)"],"organizations":["solitary","brood (2-8)"],"treasure":"standard","description_visual":"This appears to be a mass of floating intestines tangled around a fanged mouth-the tips of its coils also end in toothy maws.","group":"Qlippoth","source":"PFRPG Bestiary 2","special_abilities":[{"type":"Acid Spray","kind":"Su","details":"A nyogoth's body is full of highly corrosive digestive fluid. Every time a nyogoth is damaged by a piercing or slashing weapon, all creatures adjacent to the nyogoth take 1d6 points of acid damage (2d6 acid damage if the attack is a critical hit)."},{"type":"Horrific Appearance","kind":"Su","details":"Creatures that succumb to a nyogoth's horrific appearance become nauseated for 1d8 rounds."}],"description":"The nyogoth's role on the Abyss is that of a scavenger. Essentially mobile clumps of buoyant intestines, these writhing creatures squirt through the air in convulsive movements like an octopus gliding through water, and are constantly on the search for anything smaller than one of their many mouths (either the relatively small ones that pinch and gasp at the tips of their intestinal limbs or the larger gaping one at their cores). They can subsist on the waste and filth left behind by other denizens of the Abyss, but particularly enjoy feeding on still-living creatures.\n\nDespite their seemingly lowly role in Abyssal ecosystems, the nyogoths are far from stupid beasts. Most are nearly as intelligent as the average human, and are capable of solving relatively complex problems when it comes to securing the next meal. As outsiders, nyogoths don't need to eat to survive, yet this doesn't exempt them from hunger-a nyogoth that goes for longer than 12 hours without a meal becomes increasingly violent and erratic. Such a \"starving\" nyogoth typically fights to the death when the prospect of food is available, and may even resort to self-cannibalism, drinking its own spurting digestive juices from its wounds in a nauseating display.\n\nA typical nyogoth is 5 ft. in diameter and weighs 260 pounds, although they are known to grow much larger.","ecology":"","habitat_society":""},{"name":"Observer Robot Swarm","cr":10,"xp":9600,"alignment":"N","size":"Tiny","type":"construct","subtypes":["robot","swarm"],"init":8,"senses":[{"type":"darkvision","modifier":"60 ft."},{"type":"low-light vision"}],"ac":23,"ac_touch":17,"ac_flat_footed":18,"ac_mods":"+4 Dex, +1 dodge, +6 natural, +2 size","hp":117,"hd":"18d10+18","hdvalue":18,"fort":6,"ref":12,"will":12,"defensive_abilities":["all-around vision","hardness 10","swarm traits"],"immunities":["construct traits"],"weaknesses":["vulnerable to electricity"],"speed":[{"type":"land","speed":30},{"type":"fly","speed":60,"maneuverability":"perfect"}],"melee":"swarm (4d6 plus distraction and 2d6 fire)","space":"10 ft.","reach":"0 ft.","special_attacks":[{"type":"distraction","details":"DC 19"}],"strength":12,"dexterity":19,"intelligence":11,"wisdom":18,"charisma":3,"baseatk":18,"feats":[{"feat":"Alertness"},{"feat":"Dodge"},{"feat":"Following Step"},{"feat":"Improved Initiative"},{"feat":"Improved Lightning Reflexes"},{"feat":"Iron Will"},{"feat":"Lightning Reflexes"},{"feat":"Step Up"},{"feat":"Toughness"}],"skills":[{"skill":"Fly","value":20},{"skill":"Perception","value":30},{"skill":"Sense Motive","value":10},{"skill":"Stealth","value":20},{"skill":"Survival","value":9}],"languages":["Androffan","Common"],"sq":[{"type":"camouflage"},{"type":"transmit senses"}],"environments":["any (Numeria)"],"organizations":["solitary","cloud (2-5)"],"treasure":"none","description_visual":"This small robot is reminiscent of a beetle with a pair of pincers extending from the front of its body.","group":"Observer","source":"AP 86","special_abilities":[{"type":"Camouflage","kind":"Ex","details":"An observer robot's outer shell contains color-shifting screens that allow the creature to blend into the background. Though not truly invisible, they are hard to pinpoint. While using this ability, an observer robot gains a +8 racial bonus on Stealth checks and has concealment from creatures more than 5 ft. away."},{"type":"Transmit Senses","kind":"Ex","details":"Though observer robot swarms still maintain the ability to transmit their senses to a receiver like a normal observer robot, these rogue robots rarely do so."}],"description":"Observer robots were sometimes deployed in groups that were dependent on each other. Their instruments were networked to form a web of sensors spread out over a wide area to retrieve superior surveillance for their masters. Years after these networked robots ceased receiving orders, numerous observer robots rewrote their programming and assembled into collectives that numbered up to 1,000 individual observer robots. These swarms emerge from buried wreckage in dangerous metallic clouds that scour, confound, and burn creatures they attack.\n\nWhile swarms are typically chaotic, roiling clouds of creatures, observer robot swarms are highly organized, with hundreds of the tiny robots moving in synchronized patterns as they fly through the air. When observer robot swarms attack, the screens on their outer hulls flicker with disorienting colors that leave their enemies nauseated. They can also organize themselves into a matrix to display composite images across the screens on their collective shells. Treating their individual screens like pixels, observer robot swarms can form moving images of things that they have recorded such as displaying the terror-stricken face of their last victim. These robot swarms even cleverly use this technique to disguise themselves as churning clouds, flickering fires, or even other swarms such as bats or wasps.\n\nSince observer robot swarms spend much of their processing power transmitting and sharing senses with other robots in the swarm, they rarely transmit to other devices. Their recordings are shared among the collective, making harvesting recorded data from them extremely difficult.","ecology":"","habitat_society":""},{"name":"Pale Stranger","cr":10,"xp":9600,"alignment":"NE","size":"Medium","type":"undead","init":9,"senses":[{"type":"darkvision","modifier":"60 ft."}],"auras":["fear (10 ft., DC 21)"],"ac":25,"ac_touch":19,"ac_flat_footed":19,"ac_mods":"+2 armor, +5 Dex, +1 dodge, +3 luck, +4 natural","hp":127,"hd":"15d8+60","hdvalue":15,"fort":9,"ref":10,"will":13,"defensive_abilities":["channel resistance +4"],"dr":"10/bludgeoning and magic","immunities":["undead traits"],"sr":21,"speed":[{"type":"land","speed":30}],"ranged":"+1 pistols +15 (1d8+1/19-20/x4)","space":"5 ft.","reach":"5 ft.","special_attacks":[{"type":"pistols"},{"type":"stranger's shot"}],"strength":17,"dexterity":21,"intelligence":11,"wisdom":18,"charisma":18,"baseatk":11,"cmb":14,"cmd":33,"feats":[{"feat":"Deadly Aim"},{"feat":"Dodge"},{"feat":"Improved Critical (pistol)"},{"feat":"Improved Initiative"},{"feat":"Improved Two- Weapon Fighting"},{"feat":"Point-Blank Shot"},{"feat":"Precise Shot"},{"feat":"Quick Draw","type":"bonus"},{"feat":"Two-Weapon Fighting"}],"skills":[{"skill":"Acrobatics","value":10},{"skill":"Climb","value":11},{"skill":"Intimidate","value":22},{"skill":"Perception","value":22},{"skill":"Ride","value":15},{"skill":"Stealth","value":13},{"skill":"Swim","value":8}],"languages":["Common"],"sq":[{"type":"stranger's luck"}],"environments":["any"],"organizations":["solitary"],"treasure":"standard (leather armor, 2 pistols)","description_visual":"This nearly skeletal figure wields a pistol in each hand. Its garb is dusty and weathered, and smells of old decay.","source":"PFRPG Bestiary 3","special_abilities":[{"type":"Pistols","kind":"Su","details":"A pale stranger fights with two pistols. A pistol has a range increment of 20 ft. and deals both bludgeoning and piercing damage. At a range of up to 20 ft., a pale stranger's pistol attacks resolve as touch attacks. While pistols normally consume bullets and black powder when fired, a pale stranger's pistols supernaturally reload the instant it fires them, allowing the undead to make multiple attacks in a round with the weapons. In addition, any pistol a pale stranger wields functions as a +1 pistol. A pale stranger doesn't provoke attacks of opportunity when it fires a pistol in melee, and treats pistols as light weapons for the purposes of determining penalties from two-weapon fighting. Further rules for pistols, and firearms in general, can be found in Ultimate Combat."},{"type":"Stranger's Luck","kind":"Su","details":"A pale stranger gains a +3 luck bonus to AC and has no chance of misfire when using firearms."},{"type":"Stranger's Shot","kind":"Ex","details":"As a full-round action, a pale stranger can take careful aim with one of its firearms and take a single, ruinous shot. This single shot always resolves as a touch attack, regardless of the actual range. If the pale stranger threatens a critical hit with this shot, it automatically confirms the critical hit. Regardless of whether the shot is a critical hit or not, it deals +6d6 points of damage."}],"description":"Sometimes death itself cannot come between a gunslinger and its final revenge. When a gunslinger is slain by a hated enemy, or murdered before it can achieve vengeance against a hated foe, the anger and wrath can animate its remains as a vengeful undead monstrosity. When a pale stranger first rises, it seeks out the source of its anger to finish the job-thereafter, it wanders the desolate parts of the world looking for new victims to vent its unending rage upon.\n\nA pale stranger appears much as it did in life, though desiccated and obviously undead. Rare pale strangers have the ability to hide their undead nature and appear as they did in life using veil as a constant spell-like ability (CL equals their CR). These pale strangers are often more powerful and have class levels in gunslinger or ranger, and often attract large groups of adoring bandits and followers who may or may not realize that their murderous idol is in fact an unliving horror.\n\nA pale stranger stands 6-1/2 ft. tall and weighs 130 pounds.","ecology":"","habitat_society":""},{"name":"Peluda","cr":10,"xp":9600,"alignment":"NE","size":"Large","type":"dragon","init":5,"senses":[{"type":"darkvision","modifier":"60 ft."},{"type":"low-light vision"}],"ac":24,"ac_touch":10,"ac_flat_footed":23,"ac_mods":"+1 Dex, +14 natural, -1 size","hp":126,"hd":"11d12+55","hdvalue":11,"fort":14,"ref":8,"will":11,"defensive_abilities":["ferocity","quills"],"dr":"5/magic","immunities":["fire","paralysis","sleep"],"sr":21,"weaknesses":["vulnerable tail"],"speed":[{"type":"land","speed":30},{"type":"swim","speed":30}],"melee":"bite +18 (2d6+8), 2 claws +18 (1d6+8), tail slap +13 (3d6+4 plus poison)","space":"10 ft.","reach":"10 ft.","special_attacks":[{"type":"breath weapon","details":"50-ft. line, 6d6 fire damage, Reflex DC 20 half, usable every 1d4 rounds"},{"type":"poison"},{"type":"quill barrage"}],"strength":27,"dexterity":12,"constitution":21,"intelligence":6,"wisdom":15,"charisma":12,"baseatk":11,"cmb":20,"cmb_special":"+2 vs. bull rush","cmd":31,"cmd_special":"+2 vs. bull rush, +4 vs. trip","feats":[{"feat":"Awesome Blow"},{"feat":"Great Fortitude"},{"feat":"Improved Bull Rush"},{"feat":"Improved Initiative"},{"feat":"Iron Will"},{"feat":"Power Attack"}],"skills":[{"skill":"Climb","value":12},{"skill":"Intimidate","value":15},{"skill":"Perception","value":16},{"skill":"Stealth","value":10},{"skill":"Swim","value":30}],"languages":["Draconic"],"environments":["temperate marshes","temperate plains"],"organizations":["solitary","pair"],"treasure":"double","description_visual":"This long-necked dragon has steamy breath, a lashing tail, and a back covered in hundreds of quills.","source":"PFRPG Bestiary 4","special_abilities":[{"type":"Poison","kind":"Ex","details":"Quill-injury; save Fort DC 20; frequency 1/round for 6 rounds; effect 1d4 Con damage; cure 2 consecutive saves. The save DC is Constitution-based."},{"type":"Quill Barrage","kind":"Ex","details":"Three times per day, a peluda can fire dozens of spearlike barbs in all directions. All creatures within 15 ft. take 6d6 points of piercing damage (Reflex DC 20 half) and are subject to its poison quills. The save DC is Constitution-based."},{"type":"Quills","kind":"Ex","details":"A peluda's back and tail are covered in sharp black quills. A creature that strikes a peluda with a melee weapon, an unarmed attack, or a natural weapon takes 1d6 points of piercing damage from the peluda's quills and risks being poisoned. Weapons with reach don't endanger an attacker in this way. Any creature that grapples a peluda takes 3d6 points of piercing damage and risks being poisoned on its turn each round."},{"type":"Vulnerable Tail","kind":"Su","details":"A peluda is vulnerable to attacks against its tail. Any attack that isn't an attempt to sever the peluda's tail (including area attacks or attacks that cause piercing or bludgeoning damage) affects its body. To sever the tail, an opponent must target the tail and attempt a sunder combat maneuver with a slashing weapon. The tail is considered a separate weapon with hardness 5 and hit points equal to the peluda's HD. The opponent must deal enough damage on a single blow to reduce the tail's hit points to 0 or fewer. If the tail is severed, the peluda can no longer attack with it and takes 2d6 points of bleed damage each round."}],"description":"Peludas loathe all weak, fragile creatures smaller than themselves, especially humanoids. Some hunt in nearby farmlands before returning to their own lairs. Some are worshipped as gods by lizardfolk or other swamp creatures, though a peluda's short temper means it may eat its devotees if affronted. A typical peluda is 15 ft. long and weighs 300 pounds.","ecology":"","habitat_society":""},{"name":"Piscodaemon","cr":10,"xp":9600,"alignment":"NE","size":"Medium","type":"outsider","subtypes":["aquatic","daemon","evil","extraplanar"],"init":8,"senses":[{"type":"darkvision","modifier":"60 ft."},{"type":"detect good"},{"type":"detect magic"},{"type":"see invisibility"}],"ac":24,"ac_touch":14,"ac_flat_footed":20,"ac_mods":"+4 Dex, +10 natural","hp":137,"hd":"11d10+77","hdvalue":11,"fort":14,"ref":7,"will":9,"dr":"10/good","immunities":["acid","death effects","disease","poison"],"resists":[{"type":"cold","value":10},{"type":"electricity","value":10},{"type":"fire","value":10}],"sr":21,"speed":[{"type":"land","speed":30},{"type":"swim","speed":50}],"melee":"2 claws +18 (2d6+7/18-20/x3 plus grab and 1d6 bleed), tentacles +16 (1d10+3 plus poison)","space":"5 ft.","reach":"5 ft.","special_attacks":[{"type":"constrict","details":"2d6+10"}],"spell_like_abilities_caster_level":11,"spell_like_abilities_concentration":18,"spell_like_abilities":[{"frequency":"constant","spells":[{"spell":"detect good"},{"spell":"detect magic"},{"spell":"see invisibility"}]},{"frequency":"at-will","spells":[{"spell":"dispel magic"},{"spell":"greater teleport","details":"self plus 50 lbs. of objects only"}]},{"frequency":"1/day","spells":[{"spell":"summon","details":"level 4, 1d3 hydrodaemons 35%"}]},{"frequency":"3/day","spells":[{"spell":"fly"},{"spell":"stinking cloud"}]}],"strength":25,"dexterity":18,"constitution":24,"intelligence":14,"wisdom":15,"charisma":17,"baseatk":11,"cmb":18,"cmb_special":"+4 vs. grapple","cmd":32,"feats":[{"feat":"Critical Focus"},{"feat":"Improved Initiative"},{"feat":"Multiattack"},{"feat":"Power Attack"},{"feat":"Sickening Critical"},{"feat":"Vital Strike"}],"skills":[{"skill":"Escape Artist","value":18},{"skill":"Intimidate","value":17},{"skill":"Knowledge (planes)","value":16},{"skill":"Perception","value":16},{"skill":"Sense Motive","value":16},{"skill":"Stealth","value":18},{"skill":"Survival","value":16},{"skill":"Swim","value":29}],"languages":["Abyssal","Draconic","Infernal","telepathy 100 ft."],"sq":[{"type":"amphibious"},{"type":"augmented critical"}],"environments":["any (Abaddon)"],"organizations":["solitary","pair","knot (3-5)"],"treasure":"standard","description_visual":"This hideous cross between a lobster, an octopus, and a human threatens enemies with powerful claws and writhing tentacles.","group":"Daemon","source":"PFRPG Bestiary 2","special_abilities":[{"type":"Augmented Critical","kind":"Ex","details":"A piscodaemon's claws threaten a critical hit on an 18-20 and inf lict x3 damage on a successful critical hit."},{"type":"Poison","kind":"Ex","details":"Tentacles-injury; save Fort DC 22; frequency 1/ round for 6 rounds; effect 1d2 Con plus staggered for 1 round; cure 2 consecutive saves."}],"description":"These aquatic daemons roam the lower planes sowing misery and blight. They delight in drawn-out deaths, poisoning creatures or dismembering victims to watch them slowly bleed out. On their home plane of Abaddon, piscodaemons gravitate toward the same aquatic regions inhabited by hydrodaemons, and often the stronger among their ranks end up leading armies of hydrodaemons against their enemies. These creatures serve as sergeants in the hierarchy of Abaddon, and run their units with an excess of cruelty and violence.\n\nInstead of preying on the weak, piscodaemons enjoy targeting strong, well-armored warriors, knowing the pain of their weakening poison rests poorly on shoulders accustomed to bearing heavy weights and delivering devastating blows.\n\nPiscodaemons are 7 ft. tall and weigh 400 pounds.","ecology":"","habitat_society":""}];
